        # Extract the date from the filename
        date_pattern = r'\d{4}-\d{2}-\d{2}'
        dates = [datetime.strptime(re.search(date_pattern, f).group(), '%Y-%m-%d').date() for f in files]
        sorted_files = sorted(files, key=lambda x: dates[files.index(x)])

        # Create directories for each unique date
        dirs = {}
        for d in set([re.search(r'\[(.*?)\]', f).group(1) for f in sorted_files]):
            if d not in dirs:
                dirs[d] = []

        # Move files into their respective directories
        for f in sorted_files:
            dir_name = re.search(r'\[(.*?)\]', f).group(1)
            if dir_name in dirs:
                shutil.move(os.path.join(directory, f), os.path.join(directory, dir_name))

        return directory, dirs

