def task_func(time_strings, timezone):
    if len(time_strings) < 2:
            return 0.0

        converted_times = [datetime.strptime(ts, "%Y-%m-%d %H:%M:%S") for ts in time_strings]
        converted_times = [
            tz.localize(dt).astimezone(pytz.timezone(timezone)) for dt in converted_times
        ]
        diffs = np.abs(np.diff([dt.timestamp() for dt in converted_times]))
        avg_diff = np.mean(diffs)
        return avg_diff

