def task_func(server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5):
    # Create a TCP/IP socket
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.setblocking(0)

        try:
            sock.bind((server_address, server_port))
        except Exception as e:
            return f"Error binding socket: {e}"

        sock.listen(run_duration)

        input_sockets = [sock]

        start_time = datetime.now()
        end_time = start_time + timedelta(seconds=run_duration)

        while start_time < end_time:
            readable_sockets, _, _ = select.select(input_sockets, [], [])

            for readable_socket in readable_sockets:
                if readable_socket == sock:
                    connection, address = sock.accept()

                    if not isinstance(connection, socket._socketobject):
                        continue

                    input_sockets.append(connection)

        response_queue = queue.Queue(buffer_size)

        while True:
            ready_sockets, _, _ = select.select(input_sockets, [], [])
            for ready_socket in ready_sockets:
                if ready_socket == sock:
                    connection, address = sock.accept()

                    if not isinstance(connection, socket._socketobject):
                        continue

                    input_sockets.append(connection)

                else:
                    data = ready_socket.recv(buffer_size).decode("utf-8")
                    if not data:
                        input_sockets.remove(ready_socket)
                        ready_socket.close()
                        break

                    response_queue.put(data)

        response = ""
        while not response_queue.empty():
            response += response_queue.get().encode("utf-8")

        return (
            f"Server is running on port {server_port}.\n"
            "Data received from clients:\n"
            f"{response}\n"
            "Server is shutting down."
        )

